def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    if old_value == 0:
        return None

    absolute_change = new_value - old_value
    growth_ratio = absolute_change / old_value
    percentage_growth = growth_ratio * 100

    return {
        "value": percentage_growth,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "absolute_change": absolute_change,
            "growth_ratio": growth_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
